const ROLES=[["SOC Analyst","Monitor alerts, triage incidents, analyse logs","Networking, Linux, SIEM, log analysis","Security+, CySA+, Splunk"],["Penetration Tester","Authorised testing and reporting","Networking, Linux, web security, scripting","eJPT, PNPT, OSCP"],["DFIR Analyst","Investigate incidents, preserve evidence","Windows/Linux internals, memory and disk forensics","GCFA, GCFE, CHFI"],["Cloud Security Engineer","Secure identities, storage and workloads","AWS/Azure/GCP, IAM, IaC","AWS Security, AZ-500, CCSP"],["AppSec Engineer","Secure code, reviews, testing","Programming, OWASP Top 10, SAST/DAST","CSSLP, GWEB"],["GRC Analyst","Risk, policy, audit, compliance","ISO 27001, NIST, risk assessment","CISA, CISM, ISO 27001 LA"],["Security Architect","Design secure systems","Networks, cloud, threat modelling","CISSP, SABSA"]];

function pct(){const all=TUTS.length+LABS.length+CTF.length+1;return Math.round(Object.keys(S.done).length/all*100)}
function toggleTheme(){const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';try{localStorage.setItem('nexus-theme',dark?'dark':'light')}catch(e){}}
try{document.documentElement.dataset.theme=localStorage.getItem('nexus-theme')||'dark'}catch(e){document.documentElement.dataset.theme='dark'}
function show(p,f){$("#nav").setAttribute("aria-label","Academy navigation");$("#nav").innerHTML="<a href=../index.html class=home><img src=../assets/oj-mark.svg alt=OJ width=26 height=26> OJ // NEXUS</a>"+NAV.map(n=>`<button class="${n[0]==p?"on":""}" onclick="go('${n[0]}')">${n[1]}</button>`).join("")+`<button class="theme-toggle" onclick="toggleTheme()" title="Toggle theme">◐ Theme</button>`+(ME?`<span class='mu' style='margin-left:auto;padding:6px 10px;white-space:nowrap'>${esc(ME)}${ADMIN?' (admin)':''}</span>`:'');$("#main").innerHTML=f?f():V[p]();if(!f&&L[p])L[p]();scrollTo(0,0)}
const PAGES={dash:'index.html',path:'start.html',acad:'curriculum.html',tut:'tutorials.html',lab:'labs.html',ctf:'ctf.html',quiz:'assessments.html',career:'career.html',tracks:'tracks.html',prog:'progress.html'};
function go(p){location.href=PAGES[p]}
let PEND=()=>{};
function boot(p,fn){
  PEND=()=>{
    try {
      if(typeof V[p]!=='function'&&!fn)throw Error('Page renderer not found: '+p);
      show(p,fn?()=>'':null);
      if(fn)fn();
      if(!document.getElementById('main').textContent.trim())throw Error('Page rendered no visible content');
    } catch(err) {
      const main=document.getElementById('main');
      if(main) {
        main.innerHTML='<section class="card"><h1>Unable to open this section</h1><p>The academy encountered a loading error. Please refresh the page or return to the dashboard.</p><pre id="oj-page-error" style="white-space:pre-wrap;overflow-wrap:anywhere"></pre><p><button class="b" onclick="location.reload()">Reload page</button> <a href="index.html">Dashboard</a></p></section>';
        document.getElementById('oj-page-error').textContent=String(err&&err.message||err);
      }
      console.error('OJ Academy page error',err);
    }
  };
  PEND();
}
const qid=()=>new URLSearchParams(location.search).get('id');
