const MODE={"auth.log":"-rw-r-----","notes.txt":"-rw-r--r--","backup.sh":"-rwxrwxrwx"};
const LABS=[
{id:"l-term",cat:"Linux",title:"Terminal: investigate an SSH alert",desc:"Use a realistic simulated shell to investigate authentication logs and permissions.",run(){return`<p>Ticket 4411 · Priority: High · Host: <code>soc-gateway-01</code>. Investigate repeated SSH failures, identify the source IP and determine whether access succeeded.</p>
<div class="terminal-window"><div class="terminal-bar"><span class="terminal-dot red"></span><span class="terminal-dot yellow"></span><span class="terminal-dot green"></span><b>analyst@soc-gateway · bash</b><span class="terminal-live">● SIMULATED ENVIRONMENT</span></div><div class="term" id="tm" role="log" aria-live="polite"></div><div class="terminal-prompt"><span>analyst@soc:~$</span><input type="text" id="ti" placeholder="Enter a command… (try help)" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Terminal command"></div></div>
<div class="terminal-tools"><button class="o" style="width:auto;display:inline-block" onclick="termRun('help')">help</button><button class="o" style="width:auto;display:inline-block" onclick="termRun('ls -l')">ls -l</button><button class="o" style="width:auto;display:inline-block" onclick="termRun('grep \\\"Failed\\\" auth.log')">grep Failed auth.log</button><button class="o" style="width:auto;display:inline-block" onclick="termRun('clear')">clear</button></div>
<h3>Investigation answer</h3><p class="mu">Enter the source IP with the most failed SSH attempts. Start with <code>grep "Failed" auth.log</code> and compare sources.</p><div class="answer-row"><input type="text" id="ans" placeholder="e.g. 203.0.113.10" autocomplete="off"><button class="b" onclick="termAns()">Check answer</button></div><div id="r"></div>
<div class="box w"><b>Bonus · File permissions:</b> inspect <code>backup.sh</code> with <code>ls -l</code>, then apply least privilege using <code>chmod 750 backup.sh</code>. This terminal changes only its fictional in-browser file system.</div>`},init(){const t=$("#tm"),i=$("#ti");t.textContent="OJ // NEXUS SEC TRAINING SHELL v2.0\nType 'help' to list available commands. All files are fictional lab data.\n\n";i.focus();i.onkeydown=e=>{if(e.key=="Enter"){const c=i.value.trim();i.value="";if(c)termRun(c)}else if(e.key=="ArrowUp"){e.preventDefault();i.value=TERM_HIST[TERM_HIST.length-1]||""}else if(e.key=="ArrowDown"){e.preventDefault();i.value=""}}}}
];
const TERM_HIST=[];
function termPrint(s){const t=$("#tm");t.textContent+=(s===""?"\n":s+"\n");t.scrollTop=t.scrollHeight}
function termTokenize(s){const out=[];s.replace(/\"([^\"]*)\"|'([^']*)'|(\S+)/g,(_,a,b,c)=>{out.push(a??b??c)});return out}
function termExec(line,input){const a=termTokenize(line),cmd=a[0],args=a.slice(1),f=args.filter(x=>!x.startsWith("-"));if(!cmd)return input||"";
if(cmd==="help"||(cmd==="type"&&args[0]==="help"))return "Commands: pwd, whoami, ls [-l], cat FILE, grep [-in] TEXT FILE, wc -l FILE, head FILE, tail FILE, sort, uniq -c, chmod MODE FILE, stat FILE, history, clear, echo TEXT\nPipelines supported: grep Failed auth.log | awk ... | sort | uniq -c | sort -nr\nTip: quotes are optional for a single word; use them for phrases.";
if(cmd==="type")return args[0]==="help"?"help is a shell builtin":"type: command not found";
if(cmd==="pwd")return "/home/analyst";if(cmd==="whoami")return "analyst";if(cmd==="history")return TERM_HIST.map((x,n)=>`${n+1}  ${x}`).join("\n");
if(cmd==="clear"){$("#tm").textContent="";return ""}if(cmd==="echo")return args.join(" ");
if(cmd==="ls"){return args.includes("-l")?Object.keys(FS).map(k=>`${MODE[k]} 1 analyst analyst ${String(FS[k].length).padStart(5)} Nov 10 09:00 ${k}`).join("\n"):Object.keys(FS).join("  ")}
if(cmd==="cat"||cmd==="less")return FS[f[0]]??`${cmd}: ${f[0]||"missing file"}: No such file`;
if(cmd==="grep"){const pat=f[0],file=f[1];if(!pat||!file||!FS[file])return "grep: usage: grep [-in] PATTERN FILE";let lines=FS[file].split("\n").filter(x=>args.includes("-i")?x.toLowerCase().includes(pat.toLowerCase()):x.includes(pat));if(args.includes("-n"))lines=lines.map(x=>(FS[file].split("\n").indexOf(x)+1)+":"+x);return lines.join("\n")||"(no match)"}
if(cmd==="wc")return args.includes("-l")&&FS[f[0]]?String(FS[f[0]].split("\n").length).padStart(7)+" "+f[0]:"wc: usage: wc -l FILE";
if(cmd==="head"||cmd==="tail"){const lines=FS[f[0]]?.split("\n");return lines?(cmd==="head"?lines.slice(0,10):lines.slice(-10)).join("\n"):`${cmd}: ${f[0]||"missing file"}: No such file`}
if(cmd==="sort"){const lines=(input??(FS[f[0]]||"")).split("\n").filter(Boolean);return lines.sort((x,y)=>{let d=args.some(v=>v.includes("n"))?(parseFloat(x)-parseFloat(y)):x.localeCompare(y);return args.some(v=>v.includes("r"))?-d:d}).join("\n")}
if(cmd==="uniq"){const lines=(input??"").split("\n").filter(Boolean),out=[];for(let j=0;j<lines.length;){let k=j+1;while(k<lines.length&&lines[k]===lines[j])k++;out.push(args.includes("-c")?String(k-j).padStart(7)+" "+lines[j]:lines[j]);j=k}return out.join("\n")}
if(cmd==="awk"){const raw=args.join(" ");if(raw.includes("$i==\"from\"")||raw.includes("$i== 'from'")||raw.includes("from")){return (input||"").split("\n").map(x=>{const m=x.match(/\bfrom\s+(\S+)/);return m?m[1]:""}).filter(Boolean).join("\n")}return "awk: this training shell supports source-IP extraction with a 'from' field"}
if(cmd==="chmod"){const mode=args[0],file=args[1],m={"750":"-rwxr-x---","640":"-rw-r-----","644":"-rw-r--r--","777":"-rwxrwxrwx"}[mode];if(!FS[file]||!m)return "chmod: usage: chmod 750 FILE (supported modes: 640, 644, 750, 777)";MODE[file]=m;return `mode of '${file}' changed to ${mode} (${m})`}
if(cmd==="stat"){const file=f[0];return FS[file]?`  File: ${file}\n  Size: ${FS[file].length}\tAccess: ${MODE[file]}\n  Owner: analyst  Group: analyst`:`stat: cannot stat '${file}': No such file`}
return `${cmd}: command not found. Type help for available commands.`}
function termRun(line){if(!line)return;TERM_HIST.push(line);termPrint(`analyst@soc:~$ ${line}`);if(line==="clear"){$("#tm").textContent="";return}let result="";let pipeInput=null;for(const part of line.split("|").map(x=>x.trim())){const out=termExec(part,pipeInput);pipeInput=out;result=out}termPrint(result)}
