function webchk(){let ok=1;document.querySelectorAll(".mail input").forEach(c=>{if((c.dataset.g=="1")!=c.checked)ok=0});$("#r").innerHTML=ok?"✅ Correct: SQL injection, XSS and path traversal. Fixes: parameterised queries, output encoding, path validation, plus a WAF as an extra layer.":"❌ Not quite. Look for quotes with OR, script tags and ../ sequences.";if(ok)mark("l-web")}
