LABS.push({id:'l-pw',cat:'Crypto',title:'Password strength and cracking time',desc:'See why length and slow hashes matter.',run(){return `<p>Type a test passphrase (never a real password). Reach 60 bits of estimated entropy to complete.</p><input type='text' id='pw' oninput='pw()'><div id='r' class='card' style='margin-top:8px'>Enter text.</div>`}});
function pw(){const v=$('#pw').value;let p=0;if(/[a-z]/.test(v))p+=26;if(/[A-Z]/.test(v))p+=26;if(/[0-9]/.test(v))p+=10;if(/[^a-zA-Z0-9]/.test(v))p+=33;const b=p?Math.round(v.length*Math.log2(p)):0;const t=g=>{const s=Math.pow(2,b)/g/2;return s<60?'seconds':s<3600?Math.round(s/60)+' minutes':s<31536000?Math.round(s/86400)+' days':s<3.1536e13?Math.round(s/31536000)+' years':'millions of years or more'};$('#r').innerHTML=`Entropy estimate: <b>${b} bits</b><br>Fast hash (MD5, 10 billion guesses per second): <b>${t(1e10)}</b><br>Slow hash (bcrypt, 10 thousand guesses per second): <b>${t(1e4)}</b><br><span class='mu'>Assumes random characters. Dictionary words are far weaker.</span>`;if(b>=60)mark('l-pw')}
const INC=[['EDR alert: powershell.exe with an encoded command ran on FIN-PC-07, launched by a Word document. IOC: update-check.evil-cdn.net. First triage step?',['Delete the Word file and carry on','Isolate the host from the network and preserve evidence','Ignore it, PowerShell is a Microsoft tool'],1],['Logs show the same user logged on to FILE-SRV-02 at 10:42 from FIN-PC-07, and a new scheduled task appeared there. This indicates...',['A normal software update','A false positive','Lateral movement and persistence'],2],['Finance data on FILE-SRV-02 may have been accessed. Severity?',['P1 Critical','P3 Medium','P4 Low'],0],['Best containment now?',['Reboot all servers','Disable the user, reset credentials, block the C2 domain and isolate FILE-SRV-02','Wait for more alerts'],1],['Who is informed first?',['Post on social media','Nobody until Monday','Incident commander and management, then legal and privacy for a POPIA assessment'],2]];
LABS.push({id:'l-inc',cat:'IR',title:'Full incident: alert to written report',desc:'Triage, scope, contain, notify and write the report.',run(){return `<p>You are the on-call analyst. Work the case in order. Your case file builds as you go.</p><div id='inc'></div><div class='box' id='cf'><b>Case file</b><br></div>`},init(){incStep(0)}});
function incStep(i){const e=$('#inc');if(i>=INC.length){e.innerHTML=`<h3>Write the incident report</h3><p class='mu'>Include summary, timeline, impact, containment, recommendations and IOCs (at least 300 characters).</p><textarea id='irep' rows='9' style='width:100%;background:var(--cd);color:var(--tx);border:1px solid var(--bd);border-radius:8px;padding:8px;font:inherit'></textarea><button class='b' onclick='incRep()'>Submit report</button><div id='r'></div>`;return}const s=INC[i];e.innerHTML=`<h3>Step ${i+1}: ${s[0]}</h3>`+s[1].map((o,j)=>`<button class='o' onclick='incPick(${i},${j})'>${o}</button>`).join('')+`<div id='r'></div>`}
function incPick(i,j){const s=INC[i];if(j==s[2]){$('#cf').innerHTML+=`✔ ${s[1][j]}<br>`;incStep(i+1)}else $('#r').innerHTML='❌ Think about containment, evidence and business impact first.'}
function incRep(){const t=$('#irep').value.toLowerCase();const m=['summary','timeline','impact','containment','recommend','ioc'].filter(k=>!t.includes(k));const ok=!m.length&&t.length>=300;$('#r').innerHTML=ok?'✅ Case closed. Report accepted.':`❌ Missing: ${m.join(', ')||'detail. Write at least 300 characters.'}`;if(ok)mark('l-inc')}
function renderLab(id){const l=LABS.find(x=>x.id==id);$("#main").innerHTML=`<a href="#" onclick="go('lab');return false" style="color:var(--ac)">← Labs</a><h1>${l.title}</h1>${l.run()}`;if(l.init)l.init();scrollTo(0,0)}
function termAns(){if($("#ans").value.trim()=="203.0.113.45"){$("#r").innerHTML="✅ Correct. 203.0.113.45 generated four failed attempts and then a successful admin login at 02:14:11. Treat this as a confirmed compromise: follow the incident-response process, preserve evidence and escalate.";mark("l-term")}else $("#r").innerHTML="❌ Not yet. Search the failed entries, compare the source IPs and count how often each appears."}
function ip(s){return s.split(".").reduce((a,b)=>a*256+ +b,0)>>>0}
function dq(n){return[n>>>24,n>>16&255,n>>8&255,n&255].join(".")}
function calc(){const v=$("#cidr").value.trim().match(/^(\d+\.\d+\.\d+\.\d+)\/(\d+)$/);const o=$("#r");if(!v||+v[2]>32){o.textContent="Enter a valid CIDR";return}const p=+v[2],m=p?(0xFFFFFFFF<<(32-p))>>>0:0,n=(ip(v[1])&m)>>>0,b=(n|~m)>>>0,h=p>=31?(p==32?1:2):Math.pow(2,32-p)-2;o.innerHTML=`Mask: <b>${dq(m)}</b><br>Network: <b>${dq(n)}</b><br>Broadcast: <b>${dq(b)}</b><br>Usable hosts: <b>${h}</b>`;if(v[0].endsWith("/22")&&h==1022)mark("l-sub")}
function phish(){let ok=1;document.querySelectorAll("#fl input").forEach(c=>{if((c.dataset.g=="1")!=c.checked)ok=0});$("#r").innerHTML=ok?"✅ Perfect triage. Verdict: malicious. Action: block sender and domain, purge from mailboxes, report and check if anyone clicked.":"❌ Not quite. Select all genuine red flags and none of the normal features.";if(ok)mark("l-phish")}
function risk(){const rs=["Unpatched web server","Phishing of finance staff","Lost unencrypted laptop","Meteor hits datacentre"].map((n,i)=>[n,$("#L"+i).value*$("#I"+i).value]).sort((a,b)=>b[1]-a[1]);$("#r").innerHTML="<h3>Ranking</h3>"+rs.map(r=>`${r[1]} · ${r[0]}`).join("<br>");mark("l-risk")}
function exportProgress(){const blob=new Blob([JSON.stringify({brand:'OJ // NEXUS SEC Academy',exported:new Date().toISOString(),progress:S},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='OJ-NEXUS-SEC-progress.json';a.click();URL.revokeObjectURL(a.href)}
function filterContent(id,q){const root=document.getElementById(id);if(!root)return;const term=q.toLowerCase();root.querySelectorAll('[data-search]').forEach(el=>el.hidden=!el.dataset.search.includes(term))}
function openTut(id){location.href='tutorial.html?id='+id}
function openLab(id){location.href='lab.html?id='+id}
function openCtf(id){location.href='challenge.html?id='+id}

